"""Frozen deterministic causal attention model with an immutable KV state."""

from __future__ import annotations

from dataclasses import dataclass
import math
from typing import Iterable

import torch


Tensor = torch.Tensor


@dataclass(frozen=True)
class ModelState:
    keys: tuple[Tensor, ...]
    values: tuple[Tensor, ...]

    @property
    def length(self) -> int:
        return 0 if not self.keys else int(self.keys[0].shape[1])


class FrozenCausalLM:
    """A small attention model whose parameters are generated by fixed formulas."""

    model_name = "frozen-tinylm-v1"
    dim = 24
    heads = 3
    layers = 2

    def __init__(self, vocab_size: int) -> None:
        self.vocab_size = vocab_size
        self.head_dim = self.dim // self.heads
        self.embedding = self._matrix(vocab_size, self.dim, 0.113)
        self.position = self._matrix(512, self.dim, 0.071)
        self.wq = tuple(self._matrix(self.dim, self.dim, 0.031 + layer * 0.007) for layer in range(self.layers))
        self.wk = tuple(self._matrix(self.dim, self.dim, 0.047 + layer * 0.011) for layer in range(self.layers))
        self.wv = tuple(self._matrix(self.dim, self.dim, 0.059 + layer * 0.013) for layer in range(self.layers))
        self.wo = tuple(self._matrix(self.dim, self.dim, 0.083 + layer * 0.017) for layer in range(self.layers))
        self.wff = tuple(self._matrix(self.dim, self.dim, 0.097 + layer * 0.019) for layer in range(self.layers))
        self.lm_head = self._matrix(self.dim, vocab_size, 0.127)
        self.bias = torch.tensor([math.sin((i + 1) * 0.37) * 0.15 for i in range(vocab_size)], dtype=torch.float64)

    @staticmethod
    def _matrix(rows: int, cols: int, scale: float) -> Tensor:
        values = [
            (math.sin((r + 1) * (c + 2) * scale) + math.cos((r + 3) * (c + 1) * scale * 0.61))
            / math.sqrt(max(rows, cols))
            for r in range(rows)
            for c in range(cols)
        ]
        return torch.tensor(values, dtype=torch.float64).reshape(rows, cols)

    def empty_state(self) -> ModelState:
        shape = (self.heads, 0, self.head_dim)
        return ModelState(
            keys=tuple(torch.empty(shape, dtype=torch.float64) for _ in range(self.layers)),
            values=tuple(torch.empty(shape, dtype=torch.float64) for _ in range(self.layers)),
        )

    def advance(self, token_ids: Iterable[int], state: ModelState | None = None) -> tuple[ModelState, Tensor]:
        current = self.empty_state() if state is None else state
        logits: Tensor | None = None
        for token_id in token_ids:
            if not isinstance(token_id, int) or not 0 <= token_id < self.vocab_size:
                raise ValueError("token id outside frozen vocabulary")
            position_id = current.length
            if position_id >= self.position.shape[0]:
                raise ValueError("sequence exceeds model context")
            x = self.embedding[token_id] + self.position[position_id]
            next_keys: list[Tensor] = []
            next_values: list[Tensor] = []
            for layer in range(self.layers):
                query = (x @ self.wq[layer]).reshape(self.heads, self.head_dim)
                key = (x @ self.wk[layer]).reshape(self.heads, 1, self.head_dim)
                value = (x @ self.wv[layer]).reshape(self.heads, 1, self.head_dim)
                keys = torch.cat((current.keys[layer], key), dim=1)
                values = torch.cat((current.values[layer], value), dim=1)
                scores = torch.einsum("hd,htd->ht", query, keys) / math.sqrt(self.head_dim)
                weights = torch.softmax(scores, dim=-1)
                context = torch.einsum("ht,htd->hd", weights, values).reshape(self.dim)
                x = torch.tanh(x + context @ self.wo[layer] + x @ self.wff[layer])
                next_keys.append(keys)
                next_values.append(values)
            current = ModelState(tuple(next_keys), tuple(next_values))
            logits = x @ self.lm_head + self.bias
        if logits is None:
            raise ValueError("advance requires at least one token")
        return current, logits

    def select_next(self, logits: Tensor) -> int:
        usable = logits.clone()
        usable[:4] = -torch.inf
        return int(torch.argmax(usable).item())

    def forward_padded(self, input_ids: Tensor, attention_mask: Tensor) -> Tensor:
        """Evaluate a padded batch; active-token positions are mask cumulative positions."""
        if input_ids.ndim != 2 or attention_mask.shape != input_ids.shape:
            raise ValueError("input_ids and attention_mask must have the same rank-2 shape")
        batch, width = input_ids.shape
        output = torch.zeros((batch, width, self.vocab_size), dtype=torch.float64)
        for row in range(batch):
            state = self.empty_state()
            for column in range(width):
                if int(attention_mask[row, column].item()) == 0:
                    continue
                state, logits = self.advance([int(input_ids[row, column].item())], state)
                output[row, column] = logits
        return output
